import{i as e,r as t,s as n,t as r}from"./app-Cm-2JNjc.js";var i=JSON.parse(`{"path":"/notes/boshi-biji/gaodeng-tongji-fangfa/logistic-regression.html","title":"Logistic Regression","lang":"zh-CN","frontmatter":{"date":"2026-10-20T00:00:00.000Z"},"git":{"createdTime":1793369599000,"updatedTime":1793369599000,"contributors":[{"name":"Dawnfz-Lenfeng","username":"Dawnfz-Lenfeng","email":"2912706234@qq.com","commits":1,"url":"https://github.com/Dawnfz-Lenfeng"}]}}`),a={name:`Logistic Regression.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="logistic-regression" tabindex="-1"><a class="header-anchor" href="#logistic-regression"><span>Logistic Regression</span></a></h1><h2 id="_1-model-specification-and-interpretation" tabindex="-1"><a class="header-anchor" href="#_1-model-specification-and-interpretation"><span>1. Model Specification and Interpretation</span></a></h2><h3 id="_1-1-binary-response" tabindex="-1"><a class="header-anchor" href="#_1-1-binary-response"><span>1.1 Binary Response</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Binary Response)</p><div class="custom-container-content"><p>Let <span class="math-inline" data-tex="Y_i=1"></span> if an event occurs and <span class="math-inline" data-tex="Y_i=0"></span> otherwise. Conditional on covariates <span class="math-inline" data-tex="\\boldsymbol{x}_i"></span>, <span class="math-block" data-tex="Y_i\\mid \\boldsymbol{x}_i\\sim \\mathrm{Bernoulli}(\\pi_i),\\qquad \\pi_i=P(Y_i=1\\mid \\boldsymbol{x}_i)."></span>Therefore<span class="math-block" data-tex="E(Y_i\\mid \\boldsymbol{x}_i)=\\pi_i,\\qquad \\operatorname{Var}(Y_i\\mid \\boldsymbol{x}_i)=\\pi_i(1-\\pi_i)."></span><br> Examples: disease status, treatment response, employment status.</p></div></div><h3 id="_1-2-why-not-ordinary-linear-regression" tabindex="-1"><a class="header-anchor" href="#_1-2-why-not-ordinary-linear-regression"><span>1.2 Why Not Ordinary Linear Regression</span></a></h3><p>The linear probability model specifies<span class="math-block" data-tex="E(Y_i\\mid \\boldsymbol{x}_i)=\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta}."></span>It is unsatisfactory for a binary response:</p><ol><li>The fitted value <span class="math-inline" data-tex="\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta}"></span> is not constrained to <span class="math-inline" data-tex="[0,1]"></span>.</li><li>The response is Bernoulli, so the error term cannot be normal with constant variance.</li><li>The conditional variance<span class="math-block" data-tex="\\operatorname{Var}(Y_i\\mid \\boldsymbol{x}_i)=\\pi_i(1-\\pi_i)"></span>depends on <span class="math-inline" data-tex="\\boldsymbol{x}_i"></span>, so the errors are heteroscedastic.</li><li>A constant marginal effect of <span class="math-inline" data-tex="x"></span> on <span class="math-inline" data-tex="\\pi"></span> is implausible when <span class="math-inline" data-tex="\\pi"></span> is bounded between <span class="math-inline" data-tex="0"></span> and <span class="math-inline" data-tex="1"></span>.</li></ol><h3 id="_1-3-generalized-linear-model-and-link-functions" tabindex="-1"><a class="header-anchor" href="#_1-3-generalized-linear-model-and-link-functions"><span>1.3 Generalized Linear Model and Link Functions</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Generalized Linear Model)</p><div class="custom-container-content"><p>A generalized linear model relates the conditional mean to a linear predictor through a link function <span class="math-inline" data-tex="g"></span>:<span class="math-block" data-tex="g\\{E(Y_i\\mid \\boldsymbol{x}_i)\\}=\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta},"></span>where <span class="math-inline" data-tex="\\boldsymbol{x}_i=(1,x_{i1},\\dots,x_{ip})^\\top"></span> includes the intercept. The inverse <span class="math-inline" data-tex="g^{-1}"></span> is called the <strong>mean response function</strong>, and <span class="math-inline" data-tex="g"></span> is called the <strong>link function</strong>.</p></div></div><p>For a binary response <span class="math-inline" data-tex="E(Y_i\\mid \\boldsymbol{x}_i)=\\pi_i"></span>. The <strong>logit link</strong> is<span class="math-block" data-tex="g(\\pi_i)=\\log\\left(\\frac{\\pi_i}{1-\\pi_i}\\right),"></span>which maps <span class="math-inline" data-tex="(0,1)"></span> onto the whole real line.</p><div class="custom-container definition"><p class="custom-container-title">Definition (Logistic Regression)</p><div class="custom-container-content"><p>Logistic regression uses the logit link:<span class="math-block" data-tex="\\log\\left(\\frac{\\pi_i}{1-\\pi_i}\\right)=\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta}."></span>Solving for <span class="math-inline" data-tex="\\pi_i"></span> gives the <strong>logistic response function</strong><span class="math-block" data-tex="\\pi_i=\\frac{\\exp(\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta})}{1+\\exp(\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta})}=\\frac{1}{1+\\exp(-\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta})}."></span>The curve is sigmoidal, always lies in <span class="math-inline" data-tex="(0,1)"></span>, and is increasing in <span class="math-inline" data-tex="\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta}"></span>.</p></div></div><div class="custom-container note"><p class="custom-container-title">Note (Alternative link functions)</p><div class="custom-container-content"><p>For a binary response, other common choices of <span class="math-inline" data-tex="g"></span> are</p><ul><li><strong>Probit</strong>: <span class="math-block" data-tex="g(\\pi_i)=\\Phi^{-1}(\\pi_i)."></span></li><li><strong>Complementary log-log</strong>: <span class="math-block" data-tex="g(\\pi_i)=\\log\\{-\\log(1-\\pi_i)\\}."></span><br> The logit and probit links are symmetric about <span class="math-inline" data-tex="\\pi=0.5"></span>, in the sense that <span class="math-inline" data-tex="\\pi(-\\eta)=1-\\pi(\\eta)"></span>; the complementary log-log link is asymmetric. The choice of link changes the shape of the response curve and the interpretation of the coefficients.</li></ul></div></div><div class="custom-container note"><p class="custom-container-title">Note (Latent-variable motivation for probit)</p><div class="custom-container-content"><p>Suppose a continuous latent variable<span class="math-block" data-tex="Y_i^*=\\beta_0+\\beta_1x_i+\\varepsilon_i,\\qquad \\varepsilon_i\\sim N(0,1),"></span>and we observe <span class="math-inline" data-tex="Y_i=1\\{Y_i^*&gt;c\\}"></span>. Then<span class="math-block" data-tex="P(Y_i=1\\mid x_i)=P(\\beta_0+\\beta_1x_i+\\varepsilon_i&gt;c)=\\Phi(\\beta_0^*+\\beta_1^*x_i),"></span>where <span class="math-inline" data-tex="\\beta_0^*=\\beta_0-c"></span> and <span class="math-inline" data-tex="\\beta_1^*=\\beta_1"></span>, which is a probit model. A logistic model arises similarly if the latent error has a standard logistic distribution. This explains why the two links often give similar fitted probabilities but different coefficient scales.</p></div></div><h3 id="_1-4-odds-ratios-and-interpretation" tabindex="-1"><a class="header-anchor" href="#_1-4-odds-ratios-and-interpretation"><span>1.4 Odds Ratios and Interpretation</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Odds, Log-Odds, and Odds Ratio)</p><div class="custom-container-content"><p>For an event probability <span class="math-inline" data-tex="\\pi"></span>,<span class="math-block" data-tex="\\text{odds}=\\frac{\\pi}{1-\\pi},\\qquad \\text{log-odds}=\\log\\left(\\frac{\\pi}{1-\\pi}\\right)."></span>For a one-unit increase in <span class="math-inline" data-tex="x_j"></span>, holding the other predictors fixed,<span class="math-block" data-tex="\\log\\left\\{\\frac{\\operatorname{odds}(x_j+1)}{\\operatorname{odds}(x_j)}\\right\\}=\\beta_j,"></span>so the odds ratio is<span class="math-block" data-tex="\\operatorname{OR}=\\frac{\\operatorname{odds}(x_j+1)}{\\operatorname{odds}(x_j)}=\\exp(\\beta_j)."></span></p></div></div><table><thead><tr><th style="text-align:right;">Probability <span class="math-inline" data-tex="\\pi"></span></th><th style="text-align:right;">Odds <span class="math-inline" data-tex="\\pi/(1-\\pi)"></span></th><th style="text-align:right;">Log-odds</th></tr></thead><tbody><tr><td style="text-align:right;"><span class="math-inline" data-tex="0.20"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="0.25"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="\\log(0.25)"></span></td></tr><tr><td style="text-align:right;"><span class="math-inline" data-tex="0.50"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="1"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="0"></span></td></tr><tr><td style="text-align:right;"><span class="math-inline" data-tex="0.80"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="4"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="\\log(4)"></span></td></tr></tbody></table><p>Interpretation:</p><ul><li><strong>Continuous predictor</strong>: <span class="math-inline" data-tex="\\exp(\\beta_j)"></span> is the OR for a one-unit increase in <span class="math-inline" data-tex="x_j"></span>.</li><li><strong>Binary predictor</strong>: <span class="math-inline" data-tex="\\exp(\\beta_j)"></span> is the OR relative to the reference group.</li><li><strong>Multi-level factor</strong>: use indicator variables and specify a reference category.</li><li><span class="math-inline" data-tex="\\beta_0"></span> is the log-odds when all predictors are zero (or at their reference levels).</li></ul><p>With an interaction,<span class="math-block" data-tex="\\operatorname{logit}(\\pi)=\\beta_0+\\beta_1x+\\beta_2z+\\beta_3xz,"></span>the effect of <span class="math-inline" data-tex="x"></span> is<span class="math-block" data-tex="\\frac{\\partial\\operatorname{logit}(\\pi)}{\\partial x}=\\beta_1+\\beta_3z,"></span>so the OR for a one-unit increase in <span class="math-inline" data-tex="x"></span> is <span class="math-inline" data-tex="\\exp(\\beta_1+\\beta_3z)"></span> and depends on <span class="math-inline" data-tex="z"></span>.</p><div class="custom-container warning"><p class="custom-container-title">Warning (Linearity is on the logit scale)</p><div class="custom-container-content"><p>A linear predictor means that the <strong>log-odds</strong> are linear in <span class="math-inline" data-tex="\\boldsymbol{x}"></span>, not that <span class="math-inline" data-tex="\\pi"></span> is linear in <span class="math-inline" data-tex="\\boldsymbol{x}"></span>. The coefficient <span class="math-inline" data-tex="\\beta_j"></span> is not a change in probability. On the probability scale,<span class="math-block" data-tex="\\frac{\\partial\\pi}{\\partial x_j}=\\beta_j\\pi(1-\\pi),"></span>which depends on the value of <span class="math-inline" data-tex="\\boldsymbol{x}"></span>. Curvature can be represented by polynomial terms or splines.</p></div></div><h3 id="_1-5-probability-distribution-of-the-response" tabindex="-1"><a class="header-anchor" href="#_1-5-probability-distribution-of-the-response"><span>1.5 Probability Distribution of the Response</span></a></h3><div class="custom-container theorem"><p class="custom-container-title">Theorem (Probability Distribution of <span class="math-inline" data-tex="Y_i"></span>)</p><div class="custom-container-content"><p>The <span class="math-inline" data-tex="Y_i"></span> are independent but not identically distributed:<span class="math-block" data-tex="Y_i\\mid \\boldsymbol{x}_i\\overset{ind}{\\sim}\\mathrm{Bernoulli}(\\pi_i),\\qquad \\pi_i=\\frac{\\exp(\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta})}{1+\\exp(\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta})}."></span>The probability mass function is<span class="math-block" data-tex="f(y_i\\mid \\boldsymbol{x}_i;\\boldsymbol{\\beta})=\\pi_i^{y_i}(1-\\pi_i)^{1-y_i},\\qquad y_i\\in\\{0,1\\}."></span>There is no separate error term: all randomness is in the Bernoulli response.</p></div></div><h3 id="_1-6-study-design-prospective-and-case-control" tabindex="-1"><a class="header-anchor" href="#_1-6-study-design-prospective-and-case-control"><span>1.6 Study Design: Prospective and Case-Control</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Prospective and Retrospective Sampling)</p><div class="custom-container-content"><p>In a <strong>prospective</strong> study, subjects are sampled by exposure or covariates, and outcomes are observed subsequently. In a <strong>retrospective case-control</strong> study, subjects are sampled by outcome status, and their exposures or covariates are compared. Prospective studies can be expensive and inefficient for rare outcomes; case-control studies are often cheaper and more efficient for rare diseases. In a case-control study, the proportion of cases is determined by the sampling design and generally does not estimate the population prevalence.</p></div></div><div class="custom-container theorem"><p class="custom-container-title">Theorem (Slope Invariance under Case-Control Sampling)</p><div class="custom-container-content"><p>Suppose the population follows<span class="math-block" data-tex="\\operatorname{logit}\\{P(Y=1\\mid \\boldsymbol{x})\\}=\\beta_0+\\boldsymbol{x}^\\top\\boldsymbol{\\beta},"></span>where here <span class="math-inline" data-tex="\\boldsymbol{x}"></span> excludes the intercept and <span class="math-inline" data-tex="\\boldsymbol{\\beta}"></span> contains the corresponding slope coefficients. Let <span class="math-inline" data-tex="S=1"></span> indicate selection into the study, and assume<span class="math-block" data-tex="P(S=1\\mid Y=1,\\boldsymbol{x})=\\theta_1,\\qquad P(S=1\\mid Y=0,\\boldsymbol{x})=\\theta_0,"></span>where <span class="math-inline" data-tex="\\theta_1"></span> and <span class="math-inline" data-tex="\\theta_0"></span> do not depend on <span class="math-inline" data-tex="\\boldsymbol{x}"></span> within outcome groups. Then<span class="math-block" data-tex="P(Y=1\\mid \\boldsymbol{x},S=1)=\\frac{\\theta_1\\pi(\\boldsymbol{x})}{\\theta_1\\pi(\\boldsymbol{x})+\\theta_0\\{1-\\pi(\\boldsymbol{x})\\}},"></span>and<span class="math-block" data-tex="\\operatorname{logit}\\{P(Y=1\\mid \\boldsymbol{x},S=1)\\}=\\beta_0+\\log\\left(\\frac{\\theta_1}{\\theta_0}\\right)+\\boldsymbol{x}^\\top\\boldsymbol{\\beta}."></span></p></div></div><p><strong>Proof.</strong> By Bayes&#39; rule,<br><span class="math-block" data-tex="
P(Y=1\\mid \\boldsymbol{x},S=1)
=\\frac{P(S=1\\mid Y=1,\\boldsymbol{x})P(Y=1\\mid \\boldsymbol{x})}{P(S=1\\mid Y=1,\\boldsymbol{x})P(Y=1\\mid \\boldsymbol{x})+P(S=1\\mid Y=0,\\boldsymbol{x})P(Y=0\\mid \\boldsymbol{x})}.
"></span><br> Substituting the sampling probabilities gives the first display. Dividing the probability of a case by the probability of a control gives<br><span class="math-block" data-tex="
\\frac{P(Y=1\\mid \\boldsymbol{x},S=1)}{P(Y=0\\mid \\boldsymbol{x},S=1)}
=\\frac{\\theta_1}{\\theta_0}\\frac{\\pi(\\boldsymbol{x})}{1-\\pi(\\boldsymbol{x})}.
"></span><br> Taking logarithms yields the second display.</p><p>Thus, under outcome-dependent sampling,<br><span class="math-block" data-tex="
\\beta_0^*=\\beta_0+\\log\\left(\\frac{\\theta_1}{\\theta_0}\\right),\\qquad \\boldsymbol{\\beta}^*=\\boldsymbol{\\beta}.
"></span></p><p>Consequences:</p><ul><li>The slope coefficients, and hence the conditional odds ratios <span class="math-inline" data-tex="\\exp(\\beta_j)"></span>, can be estimated from case-control data.</li><li>The sample intercept differs from the population intercept, so absolute risks and population prevalence are not directly recoverable.</li><li>External information such as the population prevalence or the sampling fractions can be used to recover the population intercept.</li><li>This invariance is special to the logit link; it does not hold for arbitrary link functions.</li></ul><h2 id="_2-estimation" tabindex="-1"><a class="header-anchor" href="#_2-estimation"><span>2. Estimation</span></a></h2><p>Because the response is Bernoulli and its variance depends on <span class="math-inline" data-tex="\\pi_i"></span>, least squares is not appropriate. Parameters are estimated by maximum likelihood.</p><h3 id="_2-1-bernoulli-likelihood" tabindex="-1"><a class="header-anchor" href="#_2-1-bernoulli-likelihood"><span>2.1 Bernoulli Likelihood</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Bernoulli Likelihood)</p><div class="custom-container-content"><p>For independent observations,<span class="math-block" data-tex="L(\\boldsymbol{\\beta})=\\prod_{i=1}^n\\pi_i^{y_i}(1-\\pi_i)^{1-y_i},"></span>and the log-likelihood is<span class="math-block" data-tex="\\ell(\\boldsymbol{\\beta})=\\sum_{i=1}^n\\left[y_i\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta}-\\log\\{1+\\exp(\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta})\\}\\right]."></span>The maximum likelihood estimator is<span class="math-block" data-tex="\\hat{\\boldsymbol{\\beta}}=\\arg\\max_{\\boldsymbol{\\beta}}\\ell(\\boldsymbol{\\beta})."></span>There is generally no closed-form solution.</p></div></div><p><strong>Derivation.</strong> Let <span class="math-inline" data-tex="\\eta_i=\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta}"></span>. Since<br><span class="math-block" data-tex="
\\pi_i=\\frac{e^{\\eta_i}}{1+e^{\\eta_i}},\\qquad 1-\\pi_i=\\frac{1}{1+e^{\\eta_i}},
"></span><br> we have<br><span class="math-block" data-tex="
y_i\\log\\pi_i+(1-y_i)\\log(1-\\pi_i)
=y_i\\eta_i-\\log(1+e^{\\eta_i}).
"></span><br> Summing over <span class="math-inline" data-tex="i"></span> gives the log-likelihood above.</p><h3 id="_2-2-score-and-information" tabindex="-1"><a class="header-anchor" href="#_2-2-score-and-information"><span>2.2 Score and Information</span></a></h3><div class="custom-container theorem"><p class="custom-container-title">Theorem (Score Function and Fisher Information)</p><div class="custom-container-content"><p>Let <span class="math-inline" data-tex="\\boldsymbol{X}"></span> have rows <span class="math-inline" data-tex="\\boldsymbol{x}_i^\\top"></span>, and let <span class="math-inline" data-tex="\\boldsymbol{y}=(y_1,\\dots,y_n)^\\top"></span> and <span class="math-inline" data-tex="\\boldsymbol{\\pi}=(\\pi_1,\\dots,\\pi_n)^\\top"></span>. The score function is<span class="math-block" data-tex="U(\\boldsymbol{\\beta})=\\frac{\\partial\\ell(\\boldsymbol{\\beta})}{\\partial\\boldsymbol{\\beta}}=\\boldsymbol{X}^\\top(\\boldsymbol{y}-\\boldsymbol{\\pi})."></span>The observed information is<span class="math-block" data-tex="J(\\boldsymbol{\\beta})=-\\frac{\\partial^2\\ell(\\boldsymbol{\\beta})}{\\partial\\boldsymbol{\\beta}\\partial\\boldsymbol{\\beta}^\\top}=\\boldsymbol{X}^\\top\\boldsymbol{W}\\boldsymbol{X},\\qquad \\boldsymbol{W}=\\operatorname{diag}\\{\\pi_i(1-\\pi_i)\\}."></span>Because the logit is the canonical link for the Bernoulli family, the observed information equals the expected Fisher information.</p></div></div><p><strong>Proof.</strong> Differentiating the log-likelihood,<br><span class="math-block" data-tex="
\\frac{\\partial\\ell}{\\partial\\boldsymbol{\\beta}}
=\\sum_{i=1}^n\\left(y_i-\\frac{e^{\\eta_i}}{1+e^{\\eta_i}}\\right)\\boldsymbol{x}_i
=\\sum_{i=1}^n(y_i-\\pi_i)\\boldsymbol{x}_i
=\\boldsymbol{X}^\\top(\\boldsymbol{y}-\\boldsymbol{\\pi}).
"></span><br> Since <span class="math-inline" data-tex="\\partial\\pi_i/\\partial\\eta_i=\\pi_i(1-\\pi_i)"></span>,<br><span class="math-block" data-tex="
\\frac{\\partial^2\\ell}{\\partial\\boldsymbol{\\beta}\\partial\\boldsymbol{\\beta}^\\top}
=-\\sum_{i=1}^n\\pi_i(1-\\pi_i)\\boldsymbol{x}_i\\boldsymbol{x}_i^\\top
=-\\boldsymbol{X}^\\top\\boldsymbol{W}\\boldsymbol{X}.
"></span><br> If <span class="math-inline" data-tex="\\boldsymbol{X}"></span> has full column rank and <span class="math-inline" data-tex="0&lt;\\pi_i&lt;1"></span>, then <span class="math-inline" data-tex="\\boldsymbol{W}"></span> is positive definite and the log-likelihood is strictly concave. Hence the MLE is unique when it exists.</p><h3 id="_2-3-newton–raphson-and-fisher-scoring" tabindex="-1"><a class="header-anchor" href="#_2-3-newton–raphson-and-fisher-scoring"><span>2.3 Newton–Raphson and Fisher Scoring</span></a></h3><div class="custom-container theorem"><p class="custom-container-title">Theorem (Newton–Raphson and Fisher Scoring)</p><div class="custom-container-content"><p>Starting from a trial value <span class="math-inline" data-tex="\\boldsymbol{\\beta}^{(t)}"></span>, the Newton–Raphson update is<span class="math-block" data-tex="\\boldsymbol{\\beta}^{(t+1)}=\\boldsymbol{\\beta}^{(t)}+J(\\boldsymbol{\\beta}^{(t)})^{-1}U(\\boldsymbol{\\beta}^{(t)})."></span>Substituting the score and information gives<span class="math-block" data-tex="\\boldsymbol{\\beta}^{(t+1)}=\\boldsymbol{\\beta}^{(t)}+(\\boldsymbol{X}^\\top\\boldsymbol{W}^{(t)}\\boldsymbol{X})^{-1}\\boldsymbol{X}^\\top(\\boldsymbol{y}-\\boldsymbol{\\pi}^{(t)})."></span>Equivalently,<span class="math-block" data-tex="\\boldsymbol{\\beta}^{(t+1)}=(\\boldsymbol{X}^\\top\\boldsymbol{W}^{(t)}\\boldsymbol{X})^{-1}\\boldsymbol{X}^\\top\\boldsymbol{W}^{(t)}\\boldsymbol{z}^{(t)},"></span>where the working response is<span class="math-block" data-tex="z_i^{(t)}=\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta}^{(t)}+\\frac{y_i-\\pi_i^{(t)}}{\\pi_i^{(t)}(1-\\pi_i^{(t)})}."></span>This is <strong>iteratively reweighted least squares</strong> (IRLS).</p></div></div><p>Fisher scoring replaces <span class="math-inline" data-tex="J(\\boldsymbol{\\beta}^{(t)})"></span> by the expected information <span class="math-inline" data-tex="I(\\boldsymbol{\\beta}^{(t)})"></span>; for the canonical logit link the two coincide. A common starting value is <span class="math-inline" data-tex="\\boldsymbol{\\beta}^{(0)}=\\boldsymbol{0}"></span>, which gives <span class="math-inline" data-tex="\\pi_i^{(0)}=0.5"></span> for all <span class="math-inline" data-tex="i"></span>.</p><div class="custom-container warning"><p class="custom-container-title">Warning (Separation)</p><div class="custom-container-content"><p>If a covariate or a linear combination of covariates perfectly separates successes from failures, the likelihood can be increased indefinitely by sending the corresponding coefficient to <span class="math-inline" data-tex="\\pm\\infty"></span>. The MLE then does not exist, and the Wald standard errors become extremely large. This is a common cause of instability in small or sparse logistic regressions.</p></div></div><h3 id="_2-4-grouped-binomial-data" tabindex="-1"><a class="header-anchor" href="#_2-4-grouped-binomial-data"><span>2.4 Grouped Binomial Data</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Grouped Binomial Data)</p><div class="custom-container-content"><p>If covariate patterns are replicated, let <span class="math-inline" data-tex="Y_i"></span> be the number of events among <span class="math-inline" data-tex="n_i"></span> trials with common covariate vector <span class="math-inline" data-tex="\\boldsymbol{x}_i"></span>:<span class="math-block" data-tex="Y_i\\sim\\mathrm{Binomial}(n_i,\\pi_i),\\qquad \\operatorname{logit}(\\pi_i)=\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta}."></span>The log-likelihood is<span class="math-block" data-tex="\\ell(\\boldsymbol{\\beta})=\\sum_{i=1}^c\\left[y_i\\log\\pi_i+(n_i-y_i)\\log(1-\\pi_i)+\\log\\binom{n_i}{y_i}\\right]."></span></p></div></div><p>The binomial coefficient does not depend on <span class="math-inline" data-tex="\\boldsymbol{\\beta}"></span>, so the MLE and the asymptotic inference are the same as for the Bernoulli formulation. The deviance is not numerically the same, because the grouped and individual formulations use different saturated models; the difference is a constant that depends only on the data, so likelihood ratio comparisons of nested models are unchanged. Grouping is useful because it allows replicated goodness-of-fit tests.</p><div class="custom-container example"><p class="custom-container-title">Example (Dose–response data)</p><div class="custom-container-content"><p>Individuals receiving the same dose are grouped together. Each row is a binomial observation <span class="math-inline" data-tex="Y_i\\sim\\mathrm{Binomial}(50,\\pi_i)"></span> with <span class="math-inline" data-tex="\\operatorname{logit}(\\pi_i)=\\beta_0+\\beta_1x_i"></span>.</p></div></div><table><thead><tr><th style="text-align:right;">Dose <span class="math-inline" data-tex="x_i"></span> (mg)</th><th style="text-align:right;">Responders <span class="math-inline" data-tex="y_i"></span></th><th style="text-align:right;">Non-responders</th><th style="text-align:right;">Total <span class="math-inline" data-tex="n_i"></span></th></tr></thead><tbody><tr><td style="text-align:right;"><span class="math-inline" data-tex="0"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="3"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="47"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="50"></span></td></tr><tr><td style="text-align:right;"><span class="math-inline" data-tex="5"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="7"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="43"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="50"></span></td></tr><tr><td style="text-align:right;"><span class="math-inline" data-tex="10"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="15"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="35"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="50"></span></td></tr><tr><td style="text-align:right;"><span class="math-inline" data-tex="15"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="28"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="22"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="50"></span></td></tr><tr><td style="text-align:right;"><span class="math-inline" data-tex="20"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="39"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="11"></span></td><td style="text-align:right;"><span class="math-inline" data-tex="50"></span></td></tr></tbody></table><h2 id="_3-inference" tabindex="-1"><a class="header-anchor" href="#_3-inference"><span>3. Inference</span></a></h2><h3 id="_3-1-asymptotic-distribution-of-the-mle" tabindex="-1"><a class="header-anchor" href="#_3-1-asymptotic-distribution-of-the-mle"><span>3.1 Asymptotic Distribution of the MLE</span></a></h3><div class="custom-container theorem"><p class="custom-container-title">Theorem (Large-Sample Distribution of <span class="math-inline" data-tex="\\hat{\\boldsymbol{\\beta}}"></span>)</p><div class="custom-container-content"><p>Under suitable regularity conditions, the MLE is consistent and asymptotically normal:<span class="math-block" data-tex="\\hat{\\boldsymbol{\\beta}}\\overset{a}{\\sim}N_p\\left(\\boldsymbol{\\beta},\\ \\operatorname{Cov}(\\hat{\\boldsymbol{\\beta}})\\right),"></span>with<span class="math-block" data-tex="\\widehat{\\operatorname{Cov}}(\\hat{\\boldsymbol{\\beta}})=(\\boldsymbol{X}^\\top\\hat{\\boldsymbol{W}}\\boldsymbol{X})^{-1}."></span>For individual Bernoulli data,<span class="math-block" data-tex="\\hat W_{ii}=\\hat\\pi_i(1-\\hat\\pi_i);"></span>for grouped binomial data,<span class="math-block" data-tex="\\hat W_{ii}=n_i\\hat\\pi_i(1-\\hat\\pi_i)."></span>The standard error of <span class="math-inline" data-tex="\\hat\\beta_j"></span> is the square root of the <span class="math-inline" data-tex="j"></span>th diagonal element of <span class="math-inline" data-tex="\\widehat{\\operatorname{Cov}}(\\hat{\\boldsymbol{\\beta}})"></span>.</p></div></div><p>Under the same conditions, the MLE exists and is unique with probability tending to one, is consistent and asymptotically normal, and is asymptotically efficient. These are asymptotic approximations; small samples, sparse covariate patterns, or separation can make them unreliable.</p><h3 id="_3-2-wald-test-and-confidence-interval" tabindex="-1"><a class="header-anchor" href="#_3-2-wald-test-and-confidence-interval"><span>3.2 Wald Test and Confidence Interval</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Wald Test and Confidence Interval)</p><div class="custom-container-content"><p>To test <span class="math-inline" data-tex="H_0:\\beta_j=\\beta_{j0}"></span> versus <span class="math-inline" data-tex="H_1:\\beta_j\\neq\\beta_{j0}"></span>, use<span class="math-block" data-tex="z=\\frac{\\hat\\beta_j-\\beta_{j0}}{\\widehat{SE}(\\hat\\beta_j)}\\overset{a}{\\sim}N(0,1)."></span>For the common null hypothesis <span class="math-inline" data-tex="H_0:\\beta_j=0"></span>, this is simply <span class="math-inline" data-tex="z=\\hat\\beta_j/\\widehat{SE}(\\hat\\beta_j)"></span>. A <span class="math-inline" data-tex="(1-\\alpha)"></span> confidence interval for <span class="math-inline" data-tex="\\beta_j"></span> is<span class="math-block" data-tex="\\hat\\beta_j\\pm z_{1-\\alpha/2}\\widehat{SE}(\\hat\\beta_j),"></span>and exponentiating the endpoints gives a confidence interval for the odds ratio:<span class="math-block" data-tex="\\exp\\left\\{\\hat\\beta_j\\pm z_{1-\\alpha/2}\\widehat{SE}(\\hat\\beta_j)\\right\\}."></span></p></div></div><p>More generally, for <span class="math-inline" data-tex="q"></span> linear restrictions <span class="math-inline" data-tex="H_0:\\boldsymbol{R}\\boldsymbol{\\beta}=\\boldsymbol{r}"></span>, the Wald statistic is<br><span class="math-block" data-tex="
W=(\\boldsymbol{R}\\hat{\\boldsymbol{\\beta}}-\\boldsymbol{r})^\\top
\\left[\\boldsymbol{R}\\widehat{\\operatorname{Cov}}(\\hat{\\boldsymbol{\\beta}})\\boldsymbol{R}^\\top\\right]^{-1}
(\\boldsymbol{R}\\hat{\\boldsymbol{\\beta}}-\\boldsymbol{r})
\\overset{a}{\\sim}\\chi^2_q.
"></span></p><div class="custom-container note"><p class="custom-container-title">Note (Confidence interval for a fitted probability)</p><div class="custom-container-content"><p>First form a confidence interval for the linear predictor <span class="math-inline" data-tex="\\eta_0=\\boldsymbol{x}_0^\\top\\boldsymbol{\\beta}"></span>:<span class="math-block" data-tex="\\hat\\eta_0\\pm z_{1-\\alpha/2}\\sqrt{\\boldsymbol{x}_0^\\top\\widehat{\\operatorname{Cov}}(\\hat{\\boldsymbol{\\beta}})\\boldsymbol{x}_0}."></span>Then transform the endpoints by <span class="math-inline" data-tex="\\pi_0=1/(1+e^{-\\eta_0})"></span>. The resulting interval for <span class="math-inline" data-tex="\\pi_0"></span> is asymmetric on the probability scale.</p></div></div><h3 id="_3-3-likelihood-ratio-test" tabindex="-1"><a class="header-anchor" href="#_3-3-likelihood-ratio-test"><span>3.3 Likelihood Ratio Test</span></a></h3><div class="custom-container theorem"><p class="custom-container-title">Theorem (Likelihood Ratio Test)</p><div class="custom-container-content"><p>Consider<span class="math-block" data-tex="H_0:\\beta_{j_1}=\\cdots=\\beta_{j_q}=0"></span>against the alternative that at least one of these coefficients is nonzero. Fit the reduced model under <span class="math-inline" data-tex="H_0"></span> and the full model, with maximized log-likelihoods <span class="math-inline" data-tex="\\ell_R"></span> and <span class="math-inline" data-tex="\\ell_F"></span>. The likelihood ratio statistic is<span class="math-block" data-tex="G^2=2\\{\\ell(\\hat{\\boldsymbol{\\beta}}_{\\text{full}})-\\ell(\\hat{\\boldsymbol{\\beta}}_{\\text{reduced}})\\}."></span>Under <span class="math-inline" data-tex="H_0"></span> and suitable regularity conditions,<span class="math-block" data-tex="G^2\\overset{a}{\\sim}\\chi^2_q,"></span>where <span class="math-inline" data-tex="q"></span> is the number of restrictions. Reject <span class="math-inline" data-tex="H_0"></span> for large <span class="math-inline" data-tex="G^2"></span>.</p></div></div><p>Equivalently, if <span class="math-inline" data-tex="D_R"></span> and <span class="math-inline" data-tex="D_F"></span> are the deviances of the reduced and full models, then<br><span class="math-block" data-tex="
G^2=D_R-D_F.
"></span></p><h3 id="_3-4-wald-versus-likelihood-ratio" tabindex="-1"><a class="header-anchor" href="#_3-4-wald-versus-likelihood-ratio"><span>3.4 Wald versus Likelihood Ratio</span></a></h3><div class="custom-container note"><p class="custom-container-title">Note (Comparing the two tests)</p><div class="custom-container-content"><ul><li>Both tests are large-sample approximations.</li><li>The likelihood ratio test can handle one restriction or several restrictions simultaneously. It is invariant to reparameterization and is not one-sided.</li><li>The Wald test is convenient for a single coefficient or a linear combination of coefficients, and it requires fitting only the full model.</li><li>For a single <span class="math-inline" data-tex="H_0:\\beta_j=0"></span>, the two tests can lead to different conclusions because both rely on approximations. This differs from linear regression, where the <span class="math-inline" data-tex="t"></span> and <span class="math-inline" data-tex="F"></span> tests are exact under normality.</li></ul></div></div><h3 id="_3-5-accuracy-of-asymptotic-inference" tabindex="-1"><a class="header-anchor" href="#_3-5-accuracy-of-asymptotic-inference"><span>3.5 Accuracy of Asymptotic Inference</span></a></h3><div class="custom-container warning"><p class="custom-container-title">Warning (When the asymptotics may fail)</p><div class="custom-container-content"><ul><li>Fitted probabilities <span class="math-inline" data-tex="\\hat\\pi_i"></span> close to <span class="math-inline" data-tex="0"></span> or <span class="math-inline" data-tex="1"></span> are unfavorable.</li><li>The log-likelihood must be sufficiently close to quadratic around <span class="math-inline" data-tex="\\hat{\\boldsymbol{\\beta}}"></span> for <span class="math-inline" data-tex="(\\boldsymbol{X}^\\top\\hat{\\boldsymbol{W}}\\boldsymbol{X})^{-1}"></span> to estimate the covariance well.</li><li>The likelihood ratio statistic is approximately <span class="math-inline" data-tex="\\chi^2"></span> only when the sample size is large relative to the dimension of the full model.</li><li>For Bernoulli data, the deviance is not distributed as <span class="math-inline" data-tex="\\chi^2"></span>. For grouped binomial data with large <span class="math-inline" data-tex="n_i"></span>, the deviance is approximately <span class="math-inline" data-tex="\\chi^2"></span> under a correct model.</li></ul></div></div><h2 id="_4-quality-of-fit-replicated-data" tabindex="-1"><a class="header-anchor" href="#_4-quality-of-fit-replicated-data"><span>4. Quality of Fit: Replicated Data</span></a></h2><h3 id="_4-1-saturated-model" tabindex="-1"><a class="header-anchor" href="#_4-1-saturated-model"><span>4.1 Saturated Model</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Saturated Model)</p><div class="custom-container-content"><p>Suppose there are <span class="math-inline" data-tex="c"></span> covariate patterns, and pattern <span class="math-inline" data-tex="i"></span> contains <span class="math-inline" data-tex="n_i"></span> observations, of which <span class="math-inline" data-tex="y_i"></span> are events. A saturated model gives each pattern its own success probability<span class="math-block" data-tex="\\hat\\pi_i^{\\text{sat}}=\\frac{y_i}{n_i}."></span>It reproduces the observed counts exactly and attains the maximum possible likelihood for these data. The saturated model is a reference model for assessing fit, not a model for prediction.</p></div></div><h3 id="_4-2-pearson-statistic-and-deviance" tabindex="-1"><a class="header-anchor" href="#_4-2-pearson-statistic-and-deviance"><span>4.2 Pearson Statistic and Deviance</span></a></h3><div class="custom-container theorem"><p class="custom-container-title">Theorem (Pearson Chi-Square and Deviance)</p><div class="custom-container-content"><p>Let <span class="math-inline" data-tex="\\hat\\pi_i"></span> be the fitted event probability for pattern <span class="math-inline" data-tex="i"></span>, and let<span class="math-block" data-tex="E_{i1}=n_i\\hat\\pi_i,\\qquad E_{i0}=n_i(1-\\hat\\pi_i)"></span>be the expected event and non-event counts. The Pearson chi-square statistic is<span class="math-block" data-tex="X^2=\\sum_{i=1}^c\\frac{(y_i-n_i\\hat\\pi_i)^2}{n_i\\hat\\pi_i(1-\\hat\\pi_i)}=\\sum_{i=1}^c\\sum_{k=0}^1\\frac{(O_{ik}-E_{ik})^2}{E_{ik}},"></span>where <span class="math-inline" data-tex="O_{i1}=y_i"></span> and <span class="math-inline" data-tex="O_{i0}=n_i-y_i"></span>. The deviance is<span class="math-block" data-tex="D=2\\{\\ell_{\\text{sat}}-\\ell(\\hat{\\boldsymbol{\\beta}})\\}=2\\sum_{i=1}^c\\left[y_i\\log\\left(\\frac{y_i}{n_i\\hat\\pi_i}\\right)+(n_i-y_i)\\log\\left(\\frac{n_i-y_i}{n_i(1-\\hat\\pi_i)}\\right)\\right],"></span>with the convention <span class="math-inline" data-tex="0\\log 0=0"></span>. Under the null hypothesis that the model is correct, and when the expected counts are adequate,<span class="math-block" data-tex="X^2\\overset{a}{\\sim}\\chi^2_{c-p},\\qquad D\\overset{a}{\\sim}\\chi^2_{c-p},"></span>where <span class="math-inline" data-tex="p"></span> is the number of fitted regression parameters, including the intercept.</p></div></div><p>The deviance of the saturated model is zero, <span class="math-inline" data-tex="D_{\\text{sat}}=0"></span>. Both <span class="math-inline" data-tex="X^2"></span> and <span class="math-inline" data-tex="D"></span> measure the discrepancy between the fitted model and the observed data, but they use different discrepancy measures.</p><h3 id="_4-3-nested-models" tabindex="-1"><a class="header-anchor" href="#_4-3-nested-models"><span>4.3 Nested Models</span></a></h3><div class="custom-container theorem"><p class="custom-container-title">Theorem (Deviance Difference)</p><div class="custom-container-content"><p>Let <span class="math-inline" data-tex="M_R"></span> be a reduced model nested within a full model <span class="math-inline" data-tex="M_F"></span>. Then<span class="math-block" data-tex="G^2=D_R-D_F=2(\\ell_F-\\ell_R)\\overset{a}{\\sim}\\chi^2_q,"></span>where <span class="math-inline" data-tex="q"></span> is the difference in the numbers of fitted parameters. The saturated-model terms cancel in the difference.</p></div></div><h3 id="_4-4-remarks-on-the-chi-square-approximation" tabindex="-1"><a class="header-anchor" href="#_4-4-remarks-on-the-chi-square-approximation"><span>4.4 Remarks on the Chi-Square Approximation</span></a></h3><div class="custom-container warning"><p class="custom-container-title">Warning (Limitations)</p><div class="custom-container-content"><ul><li>The <span class="math-inline" data-tex="\\chi^2_{c-p}"></span> approximation requires adequate expected counts; it can be poor when the <span class="math-inline" data-tex="n_i"></span> are small.</li><li>The approximation improves as the response distribution becomes closer to Gaussian and the link becomes closer to the identity link.</li><li>With many covariate patterns and small <span class="math-inline" data-tex="n_i"></span>, the replicated-data tests are not reliable; use the individual-observation methods instead.</li></ul></div></div><h2 id="_5-quality-of-fit-individual-observations" tabindex="-1"><a class="header-anchor" href="#_5-quality-of-fit-individual-observations"><span>5. Quality of Fit: Individual Observations</span></a></h2><h3 id="_5-1-individual-bernoulli-data" tabindex="-1"><a class="header-anchor" href="#_5-1-individual-bernoulli-data"><span>5.1 Individual Bernoulli Data</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Individual Bernoulli Data)</p><div class="custom-container-content"><p>In individual-level data, each subject contributes one binary outcome:<span class="math-block" data-tex="Y_i\\mid \\boldsymbol{x}_i\\sim\\mathrm{Bernoulli}(\\pi_i),\\qquad \\operatorname{logit}(\\pi_i)=\\boldsymbol{x}_i^\\top\\boldsymbol{\\beta}."></span>If every covariate pattern is unique, then <span class="math-inline" data-tex="c=n"></span> and <span class="math-inline" data-tex="n_i=1"></span> for all <span class="math-inline" data-tex="i"></span>. The saturated model fits each binary response exactly.</p></div></div><p>The Pearson statistic and deviance can still be computed:<br><span class="math-block" data-tex="
X^2=\\sum_{i=1}^n\\frac{(y_i-\\hat\\pi_i)^2}{\\hat\\pi_i(1-\\hat\\pi_i)},
\\qquad
D=-2\\sum_{i=1}^n\\left[y_i\\log\\hat\\pi_i+(1-y_i)\\log(1-\\hat\\pi_i)\\right].
"></span><br> However, the usual <span class="math-inline" data-tex="\\chi^2_{n-p}"></span> approximation is generally not reliable, because the expected counts are all below one. These statistics should not be used to obtain goodness-of-fit p-values for individual Bernoulli data.</p><div class="custom-container warning"><p class="custom-container-title">Warning (Do not use the deviance as a <span class="math-inline" data-tex="\\chi^2"></span> test here)</p><div class="custom-container-content"><p>For individual binary data, the deviance is not approximately <span class="math-inline" data-tex="\\chi^2_{n-p}"></span>. The asymptotic theory requires replicated observations or large expected counts, neither of which is available when each covariate pattern occurs once.</p></div></div><h3 id="_5-2-hosmer–lemeshow-test" tabindex="-1"><a class="header-anchor" href="#_5-2-hosmer–lemeshow-test"><span>5.2 Hosmer–Lemeshow Test</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Hosmer–Lemeshow Goodness-of-Fit Test)</p><div class="custom-container-content"><ol><li>Fit the logistic model and compute <span class="math-inline" data-tex="\\hat\\pi_i"></span> for each subject.</li><li>Sort subjects by <span class="math-inline" data-tex="\\hat\\pi_i"></span> and divide them into <span class="math-inline" data-tex="G"></span> groups of approximately equal size (for example, deciles).</li><li>For group <span class="math-inline" data-tex="g"></span>, let <span class="math-inline" data-tex="n_g"></span> be the group size and define<span class="math-block" data-tex="O_g=\\sum_{i\\in g}y_i,\\qquad E_g=\\sum_{i\\in g}\\hat\\pi_i,"></span>and<span class="math-block" data-tex="O_g&#39;=n_g-O_g,\\qquad E_g&#39;=n_g-E_g."></span></li><li>Compute the statistic<span class="math-block" data-tex="C=\\sum_{g=1}^G\\left[\\frac{(O_g-E_g)^2}{E_g}+\\frac{(O_g&#39;-E_g&#39;)^2}{E_g&#39;}\\right]."></span><br> Under the null hypothesis of adequate fit, <span class="math-inline" data-tex="C\\overset{a}{\\sim}\\chi^2_{G-2}"></span>. A large <span class="math-inline" data-tex="C"></span> (small p-value) suggests disagreement between observed and expected event frequencies.</li></ol></div></div><p>Remarks:</p><ul><li>The grouping is somewhat arbitrary. The choice of <span class="math-inline" data-tex="G"></span> and the cutpoints can affect the p-value.</li><li>The <span class="math-inline" data-tex="\\chi^2_{G-2}"></span> approximation requires adequate expected counts.</li><li>The test has low power and is not consistent against all alternatives; failing to reject does not prove that the model is correct.</li><li>Simulation evidence supports the <span class="math-inline" data-tex="\\chi^2_{G-2}"></span> reference distribution under the usual conditions.</li></ul><h3 id="_5-3-residuals" tabindex="-1"><a class="header-anchor" href="#_5-3-residuals"><span>5.3 Residuals</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Logistic Regression Residuals)</p><div class="custom-container-content"><p>Let <span class="math-inline" data-tex="y_i\\in\\{0,1\\}"></span> and let <span class="math-inline" data-tex="\\hat\\pi_i"></span> be the fitted probability.</p><ul><li><strong>Response residual</strong>: <span class="math-block" data-tex="e_i=y_i-\\hat\\pi_i."></span></li><li><strong>Pearson residual</strong>: <span class="math-block" data-tex="r_{P,i}=\\frac{y_i-\\hat\\pi_i}{\\sqrt{\\hat\\pi_i(1-\\hat\\pi_i)}}."></span></li><li><strong>Studentized Pearson residual</strong>: <span class="math-block" data-tex="r_{SP,i}=\\frac{y_i-\\hat\\pi_i}{\\sqrt{\\hat\\pi_i(1-\\hat\\pi_i)(1-h_{ii})}}."></span></li><li><strong>Deviance residual</strong>: <span class="math-block" data-tex="r_{D,i}=\\operatorname{sign}(y_i-\\hat\\pi_i)\\sqrt{d_i},"></span>where <span class="math-block" data-tex="d_i=2\\left[y_i\\log\\left(\\frac{y_i}{\\hat\\pi_i}\\right)+(1-y_i)\\log\\left(\\frac{1-y_i}{1-\\hat\\pi_i}\\right)\\right]."></span></li><li><strong>Working residual</strong>: <span class="math-block" data-tex="r_{W,i}=\\frac{y_i-\\hat\\pi_i}{\\hat\\pi_i(1-\\hat\\pi_i)}."></span></li></ul></div></div><p>The leverage <span class="math-inline" data-tex="h_{ii}"></span> is the <span class="math-inline" data-tex="i"></span>th diagonal element of the hat matrix<br><span class="math-block" data-tex="
\\boldsymbol{H}=\\hat{\\boldsymbol{W}}^{1/2}\\boldsymbol{X}
(\\boldsymbol{X}^\\top\\hat{\\boldsymbol{W}}\\boldsymbol{X})^{-1}
\\boldsymbol{X}^\\top\\hat{\\boldsymbol{W}}^{1/2},
\\qquad
\\hat{\\boldsymbol{W}}=\\operatorname{diag}\\{\\hat\\pi_i(1-\\hat\\pi_i)\\}.
"></span></p><p>Key properties:</p><ul><li>The squared Pearson residuals sum to the Pearson statistic: <span class="math-inline" data-tex="\\sum_i r_{P,i}^2=X^2"></span>.</li><li>The squared deviance residuals sum to the deviance: <span class="math-inline" data-tex="\\sum_i r_{D,i}^2=D"></span>.</li><li>The studentized Pearson residuals have approximately unit variance, because they divide by the estimated standard deviation of <span class="math-inline" data-tex="e_i"></span>.</li><li>For grouped binomial data, replace <span class="math-inline" data-tex="y_i-\\hat\\pi_i"></span> by <span class="math-inline" data-tex="y_i-n_i\\hat\\pi_i"></span> and <span class="math-inline" data-tex="\\hat\\pi_i(1-\\hat\\pi_i)"></span> by <span class="math-inline" data-tex="n_i\\hat\\pi_i(1-\\hat\\pi_i)"></span> in the numerators and variances.</li></ul><h3 id="_5-4-residual-analysis-and-diagnostics" tabindex="-1"><a class="header-anchor" href="#_5-4-residual-analysis-and-diagnostics"><span>5.4 Residual Analysis and Diagnostics</span></a></h3><div class="custom-container note"><p class="custom-container-title">Note (Using residuals)</p><div class="custom-container-content"><ul><li>The exact distribution of residuals under the true model is unknown, so residual plots are interpreted qualitatively.</li><li>Plot residuals against fitted values or covariates. A flat lowess smooth suggests that the systematic part of the model is adequate.</li><li>Pearson and deviance residuals are often similar and can be checked with a QQ plot for outliers. They can differ substantially when the data are sparse, such as individual Bernoulli data.</li><li>Working residuals are useful for checking nonlinearity against covariates.</li><li>At the MLE, logistic regression can be written as a weighted least-squares problem with working response<span class="math-block" data-tex="z_i=\\boldsymbol{x}_i^\\top\\hat{\\boldsymbol{\\beta}}+\\frac{y_i-\\hat\\pi_i}{\\hat\\pi_i(1-\\hat\\pi_i)}"></span>and weights <span class="math-inline" data-tex="\\hat\\pi_i(1-\\hat\\pi_i)"></span>. Delete-one diagnostics such as DFBETAS and Cook&#39;s distance can therefore be computed from this weighted least-squares representation.</li></ul></div></div><h3 id="_5-5-graphical-check-of-the-fit" tabindex="-1"><a class="header-anchor" href="#_5-5-graphical-check-of-the-fit"><span>5.5 Graphical Check of the Fit</span></a></h3><div class="custom-container note"><p class="custom-container-title">Note (Haldane&#39;s empirical logit plot)</p><div class="custom-container-content"><p>For replicated data, plot<span class="math-block" data-tex="\\hat\\eta_i=\\log\\left(\\frac{y_i+0.5}{n_i-y_i+0.5}\\right)"></span>against the covariate pattern <span class="math-inline" data-tex="\\boldsymbol{x}_i"></span>. If the logistic model is appropriate, the plot should be roughly linear. When <span class="math-inline" data-tex="n_i=1"></span> or the <span class="math-inline" data-tex="n_i"></span> are small, group observations with nearby covariate values before plotting.</p></div></div><h3 id="_5-6-overdispersion" tabindex="-1"><a class="header-anchor" href="#_5-6-overdispersion"><span>5.6 Overdispersion</span></a></h3><div class="custom-container definition"><p class="custom-container-title">Definition (Overdispersion)</p><div class="custom-container-content"><p>The binomial model assumes<span class="math-block" data-tex="\\operatorname{Var}(Y_i)=n_i\\pi_i(1-\\pi_i)."></span>Overdispersion means that the observed variance is larger. One mechanism is clustering: let<span class="math-block" data-tex="Y=\\sum_{i=1}^c X_i,\\qquad X_i\\sim\\mathrm{Binomial}(k_i,p_i)"></span>independently, with <span class="math-inline" data-tex="\\sum_{i=1}^c k_i=m"></span>, <span class="math-inline" data-tex="E(p_i)=p"></span>, and <span class="math-inline" data-tex="\\operatorname{Var}(p_i)=\\tau^2p(1-p)"></span>. Then<span class="math-block" data-tex="E(Y)=mp,\\qquad \\operatorname{Var}(Y)=mp(1-p)\\left\\{1+\\tau^2\\frac{\\sum_{i=1}^c(k_i^2-k_i)}{m}\\right\\}."></span></p></div></div><p>Remarks:</p><ul><li>Overdispersion is detected when <span class="math-inline" data-tex="X^2"></span> or <span class="math-inline" data-tex="D"></span> is much larger than its residual degrees of freedom.</li><li>A simple correction estimates the dispersion parameter by<span class="math-block" data-tex="\\hat\\phi=\\frac{X^2}{\\mathrm{df}}\\quad\\text{or}\\quad\\hat\\phi=\\frac{D}{\\mathrm{df}},"></span>where <span class="math-inline" data-tex="\\mathrm{df}=n-p"></span> for individual data and <span class="math-inline" data-tex="\\mathrm{df}=c-p"></span> for grouped data.</li><li>A quasi-binomial or quasi-likelihood analysis multiplies the standard errors by <span class="math-inline" data-tex="\\sqrt{\\hat\\phi}"></span>. Alternatively, use a beta-binomial model or a model with random effects to represent the extra variability.</li></ul><h2 id="_6-summary" tabindex="-1"><a class="header-anchor" href="#_6-summary"><span>6. Summary</span></a></h2><table><thead><tr><th>Question</th><th>Method</th><th>Statistic</th><th>Reference distribution</th></tr></thead><tbody><tr><td>One coefficient</td><td>Wald</td><td><span class="math-inline" data-tex="z=(\\hat\\beta_j-\\beta_{j0})/\\widehat{SE}(\\hat\\beta_j)"></span></td><td><span class="math-inline" data-tex="N(0,1)"></span></td></tr><tr><td>Several coefficients</td><td>Likelihood ratio</td><td><span class="math-inline" data-tex="G^2=2(\\ell_F-\\ell_R)"></span></td><td><span class="math-inline" data-tex="\\chi^2_q"></span></td></tr><tr><td>Fit, replicated data</td><td>Pearson</td><td><span class="math-inline" data-tex="X^2"></span></td><td><span class="math-inline" data-tex="\\chi^2_{c-p}"></span></td></tr><tr><td>Fit, replicated data</td><td>Deviance</td><td><span class="math-inline" data-tex="D"></span></td><td><span class="math-inline" data-tex="\\chi^2_{c-p}"></span></td></tr><tr><td>Fit, individual data</td><td>Hosmer–Lemeshow</td><td><span class="math-inline" data-tex="C"></span></td><td><span class="math-inline" data-tex="\\chi^2_{G-2}"></span></td></tr></tbody></table><p>Key distinctions:</p><ul><li>The Wald test is convenient for a single coefficient or a linear combination; the likelihood ratio test compares nested models and handles several restrictions jointly.</li><li>Pearson&#39;s <span class="math-inline" data-tex="X^2"></span> and the deviance both compare the fitted model with the saturated model. Their <span class="math-inline" data-tex="\\chi^2"></span> approximations require replicated data with adequate expected counts.</li><li>For individual Bernoulli data, <span class="math-inline" data-tex="X^2"></span> and <span class="math-inline" data-tex="D"></span> can be computed but should not be referred to a <span class="math-inline" data-tex="\\chi^2"></span> distribution.</li><li>The Hosmer–Lemeshow test groups subjects by fitted probability; it is a useful diagnostic but is not an omnibus test of model correctness.</li></ul>`,97)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};